"""Publish the branding research and final click/spacing review from real evidence."""
from datetime import datetime, timezone
import hashlib
import html
import json
from pathlib import Path
import re
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
LAB = ROOT / 'output/auditoria-mesa-2026-10-12'


def read(path):
    return json.loads((ROOT / path).read_text(encoding='utf-8-sig'))


def main():
    release = read('output/android-updates-1130-27-release.json')
    native = read('output/auditoria-mesa-2026-10-12/09_validacion/android-native-smoke-1.13.0-27.json')
    windows = read('output/auditoria-mesa-2026-10-12/09_validacion/windows-start-1.13.0-27.json')
    geometry = read('output/brand-click-geometry.json')
    assert release['https_download_verified'] and release['native']['notification_icon']
    assert release['client_tests'] == 138 and release['server_tests'] == 92
    assert native['status'] == 'APROBADO' and native['notifications_initialized']
    assert native['native_process_restart_persistence'] and windows['running']
    assert windows['version'] == '1.13.0+27' and geometry['status'] == 'APROBADO'
    spec = read('branding/mesa-mark.json')
    files = sorted((ROOT / 'branding').glob('mesa-*'))
    manifest = []
    for path in files:
        data = path.read_bytes()
        item = dict(path=str(path.relative_to(ROOT)), bytes=len(data),
                    sha256=hashlib.sha256(data).hexdigest())
        if path.suffix == '.png':
            with Image.open(path) as image:
                item['dimensions'] = image.size
        manifest.append(item)
    # A conservative control-point bound is inside the documented central 66x66 zone.
    for path in spec['paths']:
        values = [float(x) for x in re.findall(r'-?\d+(?:\.\d+)?', path['d'])]
        width = path.get('width', 0)/2
        assert min(values[::2])+6-width >= 21
        assert max(values[::2])+6+width <= 87
        assert min(values[1::2])+6-width >= 21
        assert max(values[1::2])+6+width <= 87
    result = dict(version='1.13.0+27', finalized_utc=datetime.now(timezone.utc).isoformat(),
                  client_tests=138, server_tests=92, release=release, native=native, windows=windows,
                  click_geometry=geometry, brand_assets=manifest,
                  original_geometry=True, new_framework_dependencies=0,
                  adaptive_safe_zone_checked=True, user_survey_performed=False,
                  physical_android_test=False, remote_translation_configured=False,
                  qualification='Completed redesign/branding and executed scoped checks; physical device, full accessibility and exclusively remote translation remain pending.')
    (ROOT / 'output/branding-1.13.0-release.json').write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
    (ROOT / 'branding/asset-manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    report = '''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mesa · Identidad y comprobación final</title><style>
:root{--bg:#f6f7f2;--surface:#fffefb;--ink:#242b26;--muted:#515c53;--green:#25634b;--line:#dce3dc;color-scheme:light dark}*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 system-ui,Segoe UI,sans-serif}main{max-width:1100px;margin:auto;padding:32px 20px 72px}header,section{background:var(--surface);padding:28px;border:1px solid var(--line);border-radius:28px;margin:20px 0}h1{font-size:clamp(32px,5vw,48px);line-height:1.15;letter-spacing:-1px}h2{font-size:25px;line-height:1.3;color:var(--green)}h3{font-size:20px}a{color:var(--green);text-underline-offset:4px}img{max-width:100%;display:block;border-radius:24px}p{max-width:82ch}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:24px}.screens{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.screens img{width:100%;max-height:640px;object-fit:contain}.table{overflow:auto}table{border-collapse:collapse;width:100%;min-width:600px;font-size:14px}td,th{padding:12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.badge{display:inline-block;padding:8px 16px;background:#e1efe6;color:#123b2b;border-radius:30px}.notice{border-left:4px solid #a54f32;padding-left:20px}small{color:var(--muted)}li{margin:8px 0}code{font:14px/1.5 ui-monospace,Consolas,monospace}@media(max-width:650px){main{padding:12px}section,header{padding:20px}.grid,.screens{grid-template-columns:1fr}}@media(prefers-color-scheme:dark){:root{--bg:#171d19;--surface:#1d2923;--ink:#edf3ed;--muted:#bbc8bd;--green:#9ed8b8;--line:#415047}}
</style><main><header><span class="badge">Mesa 1.13.0+27 · Entrega comprobada</span><h1>La cocina que compartes.</h1><p>Rediseño de la aplicación, identidad visual nueva y revisión de bordes, espacios e interacción. El trabajo se implementó en Windows y Android, conservando datos y funciones. La versión final supera las comprobaciones ejecutadas; las dependencias y ensayos pendientes aparecen al final.</p><p><a href="https://starfly.tailc69897.ts.net:9443/descargar/Mesa-Android-1.13.0-27.apk">Descargar APK firmada</a> · <a href="output/branding-1.13.0-release.json">Evidencia final JSON</a> · <a href="auditoria-rediseno-mesa.html">Dossier del rediseño funcional</a></p><img src="branding/mesa-identidad.png" alt="Logo de Mesa: cuenco, m y hoja; pruebas de tamaños de 16 a 96 píxeles"></header>
<section><h2>1. Transformación y problema resuelto</h2><p>Se pasa de utensilios genéricos y estilos separados a un símbolo original que se reconoce como comida y contiene una m. Se mantienen nombre y verde para conservar continuidad; el cuenco aporta cocina doméstica, la m vincula el dibujo a Mesa y la hoja es un acento secundario. Es una decisión de diseño, no una preferencia de usuarios ya demostrada.</p><p>La app conserva la reorganización anterior: lectura despejada, menú contextual de opciones, categorías y filtros, acciones primarias claras y ajuste a escritorio/móvil. Se corrigió el botón flotante sobre el recetario vacío y la eliminación del recurso de notificaciones en Android release. La tarjeta y su botón Favorita se prueban como acciones diferentes.</p>
<h2>2. Mercado: qué se consultó y qué significa</h2><div class="table"><table><tr><th>Referencia primaria</th><th>Posicionamiento publicado</th><th>Decisión para Mesa</th></tr>
<tr><td><a href="https://www.paprikaapp.com/help/windows/">Paprika</a></td><td>Gestión, importación y cocina; la actualización beta <a href="https://paprikaapp.com/news/2026/09/28/paprika-4-is-now-in-open-beta/">Paprika 4</a> anuncia también renovación de interfaz/icono.</td><td>La identidad acompaña herramientas fiables; no sustituye cantidades ni guardado.</td></tr>
<tr><td><a href="https://cookpad.com/es">Cookpad</a></td><td>Cocina doméstica, intercambio y ayuda entre personas.</td><td>Tono cálido, familiar y directo; evitar apariencia de panel técnico.</td></tr>
<tr><td><a href="https://samsungfood.com/recipe-box-app/">Samsung Food</a></td><td>Guardar, encontrar y organizar recetas.</td><td>La receta es protagonista; el logo tiene un lugar estable y discreto.</td></tr>
<tr><td><a href="https://pages.kitchenstories.com/en/app">Kitchen Stories</a></td><td>Descubrir recetas y acompañar su preparación.</td><td>Lectura clara, fotos útiles y modo cocina accesible.</td></tr>
<tr><td><a href="https://www.recipekeeperonline.com/about">Recipe Keeper</a></td><td>Recetario entre dispositivos.</td><td>Reconocimiento común del símbolo en Windows y Android.</td></tr></table></div><p>Este es un análisis cualitativo de sitios oficiales, no un ranking por descargas o cuota de mercado. No se afirma haber usado cuentas privadas ni medido preferencias de los usuarios de esas aplicaciones.</p>
<h2>3. Encuestas y estudios: evidencia con límites</h2><p><a href="https://www.ipsos.com/en-uk/be-distinctive-everywhere">Ipsos y JKR (2023)</a> probaron activos de marca con más de 26.000 participantes globales. Solo el 15% de los activos evaluados alcanzó su nivel máximo de distintividad; los logos alcanzaron ese nivel en el 19% de los casos. Evalúan atribución de marca, no cuál logo de recetas gusta más. Se aplica como criterio: símbolo propio, continuidad y uso consistente; no basta escoger un color popular.</p><p><a href="https://onlinelibrary.wiley.com/doi/10.1002/mar.20546">Westerman y colaboradores (2012)</a> encontraron preferencia por formas redondeadas en dos experimentos con envases. Apoya explorar un lenguaje suave, pero el contexto era chocolate/agua/lejía, no una app de cocina: no demuestra una preferencia universal por este dibujo.</p><p><a href="https://pure.psu.edu/en/publications/how-re-designing-angular-logos-to-be-rounded-shapes-brand-attitud/">Walsh, Winterich y Mittal (2011)</a> muestran que la respuesta al cambio depende del vínculo con la marca y del contexto de los consumidores. Por eso se conserva nombre y familia cromática mientras se renueva el símbolo.</p><p class="notice">No se realizó una encuesta propia ni se inventan votos, satisfacción, porcentajes de éxito o una victoria frente a otras propuestas. La aceptación concreta del nuevo logo por tu familia sigue sin medirse. La elección es profesional y respaldada por evidencia indirecta.</p>
<h2>4. Alternativas y elección</h2><div class="table"><table><tr><th>Dirección evaluada</th><th>Ventaja</th><th>Limitación</th></tr><tr><td>Plato y cubiertos</td><td>Categoría culinaria clara</td><td>Muy genérico; poca asociación con el nombre Mesa</td></tr><tr><td>M aislada</td><td>Muy legible a tamaño pequeño</td><td>No comunica recetas por sí sola</td></tr><tr><td>Cuenco + m de vapor, elegido</td><td>Combina comida, inicial y formas calmadas</td><td>La lectura simbólica necesita validación humana; la hoja se pierde en tamaños muy pequeños</td></tr></table></div><p>No se asignan puntuaciones de mercado ficticias a estas alternativas. Se elige la tercera por equilibrio de reconocimiento culinario, legibilidad y coherencia con una app familiar.</p></section>
<section><h2>5. Sistema y entregables de marca</h2><p>Maestro vectorial en <code>branding/mesa-mark.json</code>. De la misma geometría salen SVG, iconos de cinco densidades Android, foreground/background adaptativos, monocromo, icono Windows de 16 a 256 px y dibujo Flutter. Verde #25634B, marfil #FFFEFB y acento #9ED8B8, compatibles con el sistema ya implementado. La palabra mesa mantiene minúsculas y una tipografía de sistema legible; el símbolo es independiente de fuentes.</p><p><a href="branding/mesa-logo.svg">Logo SVG</a> · <a href="branding/mesa-icon.svg">Icono SVG</a> · <a href="branding/mesa-monochrome.svg">Monocromo SVG</a> · <a href="branding/mesa-icon-512.png">PNG 512</a> · <a href="branding/asset-manifest.json">Identidad e integridad de archivos</a></p><p>Según <a href="https://developer.android.com/develop/ui/compose/system/icon_design_adaptive">Android Developers</a>, el icono adaptativo separa fondo y primer plano, admite máscaras de fabricantes y monocromo en launchers compatibles. Se comprobó que las cotas conservadoras de la geometría quedan dentro de la zona central 66 × 66 de un lienzo 108 × 108. El icono de tienda se exporta por separado sin redondeo horneado, siguiendo <a href="https://developer.android.com/distribute/google-play/resources/icon-design-specifications">las especificaciones de Google Play</a>; no se publica Mesa en Play por esta tarea.</p>
<h2>6. Presentación e interacciones</h2><p>Inicio con símbolo y «La cocina que compartes», tema claro/oscuro y un estado de apertura real. Se muestra mientras se inicializa el recetario; no se añade tiempo mínimo, publicidad ni espera decorativa. El inicio nativo Android y el primer estado Flutter comparten el emblema, conforme al modelo de <a href="https://developer.android.com/develop/ui/views/launch/splash-screen">SplashScreen de Android</a>. Con movimiento reducido se omite el indicador animado.</p><p>La marca no es un botón falso. La navegación mantiene ubicación seleccionada, controles con foco, botones desactivados cuando corresponde y feedback Material. Se conservan transiciones breves de 180 ms, sin movimiento continuo del logo.</p>
<div class="screens"><img src="output/screenshots/mesa-brand-launch-320.png" alt="Inicio oscuro con texto grande en 320 píxeles"><img src="output/screenshots/mesa-simple-390.png" alt="Recetario móvil final con logo nuevo"><img src="output/auditoria-mesa-2026-10-12/03_observacion_ui/android-final-cooking.png" alt="Modo cocina real del emulador de lanzamiento"></div><small>Los dos primeros son renders Flutter con fixtures; el tercero es un emulador Android x86_64 de lanzamiento. Ninguno se presenta como teléfono físico.</small></section>
<section><h2>7. Revisión final de bordes, espacios y clics</h2><p>Radios centralizados: campos 24, botones 26, tarjetas 28, diálogos 32; navegación y filtros en píldoras. El emblema usa su propia proporción (26/96 del lado) para mantener el mismo dibujo al escalar, no para imitar un botón. La tarjeta recorta imagen, contorno y tinta dentro de su borde; el foco/hover añade contorno sin cambiar la distribución.</p><p>Se revisaron recetario, filtros, editor, receta, vista previa, cocina, semana, compra, ajustes y menús con capturas de 320, 390 y 1360 px, incluyendo temas y texto ampliado. Los controles secundarios siguen dentro de grupos y menús, no se superponen como barras adicionales. La revisión visual es de esos estados, no de todas las combinaciones posibles.</p><div class="table"><table><tr><th>Medición real en 320 × 640</th><th>Resultado</th></tr><tr><td>Cuatro destinos inferiores</td><td>74 × 76 px cada uno; sin solaparse</td></tr><tr><td>Nueva receta</td><td>Altura 56 px; separación de 16 px respecto a navegación</td></tr><tr><td>Filtros rápidos</td><td>Altura táctil 48 px; separación horizontal de 8 px</td></tr><tr><td>Tarjeta / favorito</td><td>Pulsar favorito ejecuta solo favorito; pulsar contenido abre; teclado activa un solo control enfocado</td></tr><tr><td>Primera receta</td><td>Una sola acción; sin FAB sobre el mensaje vacío; desplazamiento permite alcanzarla</td></tr></table></div><p><a href="output/brand-click-geometry.json">Geometría medida</a>. El área táctil puede ser mayor que la superficie visible: facilita acertar y no representa un borde roto. Para desplazar listas se usan zonas libres del botón flotante; un gesto iniciado sobre un botón debe respetar su función.</p></section>
<section><h2>8. Arquitectura y rendimiento</h2><p>Sin nuevas dependencias de framework, migración ni modelos adicionales. El símbolo Flutter utiliza paths y CustomPainter estable; el inicio no obliga a cargar fotos ni a traducir antes de mostrar la marca. Las fotos siguen siendo referencias en línea con memoria temporal de visualización. No se afirma una mejora porcentual ni se certifica rendimiento equivalente: falta una comparativa antes/después en hardware físico.</p>
<h2>9. Pruebas y estado funcional</h2><p><strong>138 pruebas Flutter aprobadas, análisis limpio y 92 pruebas de servidor aprobadas.</strong> El servidor no cambió durante la identidad; su suite de 92 se conserva de la fase funcional. Windows 1.13.0 responde con una ventana real. APK ARM64 firmada con el certificado familiar original, con registro nativo y recurso de notificación; descarga HTTPS completa verificada por tamaño y SHA-256.</p><p>Se repitió el ensayo Android x86_64 con main.dart de producción: crear/guardar receta con cantidades, cocinar, cerrar y reiniciar el proceso, buscar la receta persistida y visitar Recetas/Semana/Compra/Mi espacio. La inicialización de notificaciones supera el ensayo; la entrega de alarmas con pantalla bloqueada no se certifica con esta prueba.</p><p>El dossier previo distingue pruebas de reglas, HTTP simulado, FastAPI en proceso y peticiones reales. No equivale a probar todos los catálogos, traducciones o móviles existentes. Se conserva la APK anterior 1.12.0, las evidencias de fallos del laboratorio y sus correcciones.</p>
<h2>10. Archivos, reproducción y límites</h2><p><code>client/lib/brand.dart</code>, <code>brand_paths.dart</code>, <code>ui.dart</code>, <code>library.dart</code>; recursos Android de iconos/splash y Windows app_icon.ico; <code>client/test/brand_interaction_test.dart</code>; <code>scripts/make_brand_assets.py</code>, <code>verify_android.py</code>, <code>verify_android_ui_smoke.py</code>. El comando antiguo make_icons.py delega en el generador nuevo para no recuperar accidentalmente la identidad anterior.</p><p>Reproducir: generar activos desde JSON, formatear el helper Dart generado, ejecutar <code>scripts/check_client.ps1</code>, compilar con <code>scripts/build.ps1</code> y verificar publicación. El ensayo de emulador requiere MesaTest y una compilación x86_64 con <code>-PmesaAbis=x86_64</code>; esta variante no se entrega al teléfono. El número de versión debe incrementarse si cambian los bytes de una APK ya publicada.</p><p class="notice">Pendientes: teléfono ARM64 físico, ciclo entre dos dispositivos físicos por Tailscale, TalkBack/Narrador y conformidad completa WCAG, alarma/instalación real según permisos y comparación de rendimiento. La traducción exclusivamente remota/gratuita sigue sin configurarse: el motor existente Windows/Android permanece activo. Tampoco se ha demostrado con una encuesta propia que este logo sea el favorito del público.</p></section><footer>Mesa 1.13.0+27 · Evidencias y preferencias declaradas por separado.</footer></main></html>'''
    (ROOT / 'identidad-y-comprobacion-mesa.html').write_text(report, encoding='utf-8')
    print(json.dumps(dict(report='identidad-y-comprobacion-mesa.html', version=result['version'],
                          tests=[138, 92], assets=len(manifest)), ensure_ascii=False))


if __name__ == '__main__':
    main()

